<div class="form-panel"><h3>Ask about your area</h3><form action="{{ route('quote.create') }}" method="get"><div class="field"><label for="postcode">UK postcode</label><input id="postcode" name="postcode" autocomplete="postal-code" maxlength="12" required placeholder="For example, SW1A 1AA"></div><div class="field"><label for="service">Service</label><select id="service" name="service"><option value="domestic">Domestic cleaning</option><option value="commercial">Commercial cleaning</option><option value="care_home">Care-home cleaning</option></select></div><button class="button">Continue to your enquiry ↗</button><p class="hint">We’ll confirm coverage after reviewing your enquiry.</p></form></div>
